/**
 * lib/bim-flow/real-feed.ts — A labelled set of the person's own BIM lines
 *
 * Every line is verbatim from the BIM feed (`brain2-telegram-feed`, Oct 14 – Oct 31, 2026), with its
 * real send time and the two lines before it, as the lab would see them. The labels say what a good
 * run does, worded from the plan (`docs/BIM_FLOW_HANDOFF.md`, "an eval set: label real feed messages
 * per gate") and from what the person asked BIM for in these same texts:
 * - `family`: the first route of the routed log flow (doing, keeping, self, people, or none).
 * - `act`: the activity pen (named as in their vault), how the line sits in time, a stated clock,
 *   minutes left. `painted` / `accepted`: the block they painted or accepted for it, when one exists.
 * - `keep`: the list it belongs on. `hard` says why a word search cannot find it. `build`: the list
 *   does not exist yet.
 * - `self`, `people`, `habit`, `place`, `nil` (a name the vault lacks).
 *
 * `REAL_PAIRS` asks one thing of two lines one or two apart: is the earlier one needed to read the
 * later one? The person asked for this check in BIM on Oct 30 ("are these 2 messages connected?").
 *
 * Labels were set by hand on 2026-11-01. Code-only tests are `real-feed.test.ts` and
 * `real-vault.test.ts`; the model scoring is `real-feed.live.test.ts`. Like `tests-real.ts`, the
 * text is private and committed with the repo.
 */

export interface RealWant {
  family: "doing" | "keeping" | "self" | "people" | "none"
  /** [pen, relation, since clock, minutes left] */
  act?: [string, "starting" | "doing_now" | "finished" | "did_earlier", string?, number?]
  keep?: string
  self?: "intake" | "mood" | "body" | "dream"
  people?: string[]
  nil?: string[]
  habit?: string[]
  place?: string
  painted?: string
  accepted?: string
  hard?: string
  build?: string
}

export interface RealLine {
  id: string
  at: string
  text: string
  prior: { text: string; at: string }[]
  want: RealWant
}

export interface RealPair {
  text: string
  at: string
  earlier: string
  earlierAt: string
  linked: boolean
}

